package com.fasterxml.jackson.core.io;

import com.fasterxml.jackson.core.JsonEncoding;
import com.fasterxml.jackson.core.io.BufferRecycler;
import com.fasterxml.jackson.core.util.BufferRecycler;
import com.fasterxml.jackson.core.util.TextBuffer;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for IOContext._verifyRelease.
 * Since the method is protected, we use a subclass or reflection to access it.
 */
public class IOContext__verifyRelease_TriageGen0Test {

    private IOContext ioContext;

    @Before
    public void setUp() {
        // Using null for BufferRecycler as it is not used by the method under test
        ioContext = new IOContext(null, null, true);
    }

    /**
     * Wrapper class to expose the protected method for testing.
     */
    private static class TestableIOContext extends IOContext {
        public TestableIOContext() {
            super(null, null, true);
        }

        @Override
        public void _verifyRelease(char[] toRelease, char[] src) {
            super._verifyRelease(toRelease, src);
        }
    }

    private TestableIOContext testableIoContext;

    @Before
    public void setUpWrapper() {
        testableIoContext = new TestableIOContext();
    }

    @Test
    public void testVerifyRelease_SameBuffer_ShouldNotThrow() {
        char[] buffer = new char[10];
        // Condition: (toRelease != src) is false. Should not throw.
        testableIoContext._verifyRelease(buffer, buffer);
    }

    @Test
    public void testVerifyRelease_DifferentBuffer_LargerToRelease_ShouldNotThrow() {
        char[] src = new char[10];
        char[] toRelease = new char[11];
        // Condition: (toRelease != src) is true AND (toRelease.length <= src.length) is false.
        // Result: true && false -> false. Should not throw.
        testableIoContext._verifyRelease(toRelease, src);
    }

    @Test
    public void testVerifyRelease_DifferentBuffer_EqualLength_ShouldThrow() {
        char[] src = new char[10];
        char[] toRelease = new char[10];
        // Condition: (toRelease != src) is true AND (toRelease.length <= src.length) is true.
        // Result: true && true -> true. Should throw.
        assertThrows(IllegalArgumentException.class, () -> {
            testableIoContext._verifyRelease(toRelease, src);
        });
    }

    @Test
    public void testVerifyRelease_DifferentBuffer_SmallerToRelease_ShouldThrow() {
        char[] src = new char[10];
        char[] toRelease = new char[5];
        // Condition: (toRelease != src) is true AND (toRelease.length <= src.length) is true.
        // Result: true && true -> true. Should throw.
        assertThrows(IllegalArgumentException.class, () -> {
            testableIoContext._verifyRelease(toRelease, src);
        });
    }

    @Test
    public void testVerifyRelease_Nulls_ShouldThrow() {
        // toRelease != src is true (null != null is false, but here we check if they are the same reference)
        // Actually, if both are null, toRelease != src is false.
        // If one is null, it depends on the length check.

        // Case: both null -> (null != null) is false -> No throw
        testableIoContext._verifyRelease(null, null);

        // Case: toRelease is null, src is not null -> (null != src) is true, (0 <= length) is true -> Throw
        assertThrows(NullPointerException.class, () -> {
            testableIoContext._verifyRelease(null, new char[10]);
        });
    }
}
